'use strict';
const assert=require('assert'),crypto=require('crypto'),fsp=require('fs').promises,fs=require('fs'),os=require('os'),path=require('path');
const {THREADS}=require('./bridge/mac_codex_app_employee_bootstrap'),{ALLOWED_UNMANAGED_TOP_LEVEL}=require('./bridge/mac_skill_bundle_shared_root_contract'),adoption=require('./bridge/mac-employee-training/adopt_step01_skill_bundle_v2');
const hash=v=>crypto.createHash('sha256').update(v).digest('hex');async function write(p,v){await fsp.mkdir(path.dirname(p),{recursive:true});await fsp.writeFile(p,JSON.stringify(v,null,2)+'\n');}
class FakeClient{
  constructor(root,o={}){this.root=root;this.o=o;this.started=[];this.turns=new Map(o.turns||[]);this.reads=0;this.firstStartReads=null;}
  async start(){}
  close(){}
  async request(method,p){
    if(method==='account/read')return{account:{type:'chatgpt'},requiresOpenaiAuth:true};
    if(method==='model/list')return{data:[{id:'native-default',model:'gpt-native-default',isDefault:true,hidden:false}]};
    const index=THREADS.findIndex(x=>x.thread_id===p.threadId),e=THREADS[index];
    if(method==='thread/resume'){assert.equal(p.modelProvider,'openai');assert.equal(p.model,'gpt-native-default');return{};}
    if(method==='thread/read'){this.reads++;const turn=this.turns.get(p.threadId);return{thread:{id:p.threadId,name:e.title,cwd:this.root,status:{type:this.o.activeIndex===index?'active':'notLoaded'},turns:turn?[turn]:[]}};}
    if(method==='turn/start'){assert.equal(p.model,'gpt-native-default');if(this.firstStartReads===null)this.firstStartReads=THREADS.length;const id='turn-'+e.employee,text=p.input[0].text,raw=text.match(/\{"status":"adopted_read_only".*\}$/m)[0],response=this.o.wrongResponseIndex===index?raw.replace('adopted_read_only','wrong'):raw,turn={id,status:this.o.turnErrorIndex===index?'failed':'completed',error:this.o.turnErrorIndex===index?{message:'synthetic'}:null,items:[{type:'agentMessage',text:response}]};this.started.push({threadId:p.threadId,id});this.turns.set(p.threadId,turn);return{turn};}
    throw new Error(method);
  }
  async waitForTurn(thread){const index=THREADS.findIndex(x=>x.thread_id===thread);if(this.o.failIndex===index)throw new Error('synthetic_partial_failure');return this.turns.get(thread);}
}
async function fixture(root){const candidatePath=path.join(root,'candidate.json'),installPath=path.join(root,'install.json'),parityPath=path.join(root,'parity.json'),entry=path.join(root,'entry.py'),manifestRel='bundle.manifest.json',manifestPath=path.join(root,manifestRel);await fsp.writeFile(entry,'entry');await fsp.writeFile(manifestPath,'manifest');const entrySha=hash(await fsp.readFile(entry)),manifestSha=hash(await fsp.readFile(manifestPath)),skills=Array.from({length:13},(_,i)=>'skill-'+i);await write(candidatePath,{schema_version:'niannian_step01_hq_full_toolchain_contract_v1',status:'blocked_install_pending',execution_authority_granted:false,entrypoint:{exact_path:entry,sha256:entrySha},bundle_v2:{manifest:{project_relative_path:manifestRel,sha256:manifestSha}}});await write(installPath,{schema_version:'niannian_mac_skill_bundle_install_receipt_v2',status:'installed_verified',bundle_id:'niannian-mac-production-skills-v2',managed_skills:13,managed_file_count:127,installed_file_count:127,skills,allowed_unmanaged_top_level:[...ALLOWED_UNMANAGED_TOP_LEVEL],unmanaged_top_level_entries:[...ALLOWED_UNMANAGED_TOP_LEVEL],unmanaged_preserved:true,manifest_sha256:manifestSha,source_snapshot_sha256:'b'.repeat(64),real_delivery:false});await write(parityPath,{schema_version:'niannian_mac_skill_bundle_parity_receipt_v2',status:'exact_parity_verified',bundle_id:'niannian-mac-production-skills-v2',managed_skills:13,managed_file_count:127,skills:13,files:127,allowed_unmanaged_top_level:[...ALLOWED_UNMANAGED_TOP_LEVEL],unmanaged_top_level_entries:[...ALLOWED_UNMANAGED_TOP_LEVEL],unmanaged_preserved:true,manifest_sha256:manifestSha,source_snapshot_sha256:'b'.repeat(64),real_delivery:false});return{candidatePath,installPath,parityPath};}
async function main(){const root=await fsp.mkdtemp(path.join(os.tmpdir(),'v2-adoption-'));try{const f=await fixture(root),config=path.join(root,'config.toml');await fsp.writeFile(config,'model_provider="codex_local_access"\n[model_providers.codex_local_access]\nenv_key="KRILL_CODEX_API_KEY"\nwire_api="responses"\nrequires_openai_auth=false\n');const common={...f,projectRoot:root,configPath:config,readbackIntervalMs:1};const client=new FakeClient(root),output=path.join(root,'out'),result=await adoption.run({...common,outputRoot:output,client});assert.equal(result.status,'verified');assert.equal(result.completed,5);assert.equal(client.started.length,5);assert.equal(client.firstStartReads,5);assert(result.manifest_evidence.sha256);const replayClient=new FakeClient(root),replayed=await adoption.run({...common,outputRoot:output,client:replayClient});assert.equal(replayed.replay,true);assert.equal(replayClient.started.length,0);
const activeClient=new FakeClient(root,{activeIndex:3});await assert.rejects(()=>adoption.run({...common,outputRoot:path.join(root,'active'),client:activeClient}),/v2_adoption_active_turn:04/);assert.equal(activeClient.started.length,0);assert.equal(activeClient.reads,4);
const partialRoot=path.join(root,'partial'),partialClient=new FakeClient(root,{failIndex:3});await assert.rejects(()=>adoption.run({...common,outputRoot:partialRoot,client:partialClient}),/synthetic_partial_failure/);assert.equal(partialClient.started.length,4);for(let i=1;i<=3;i++)assert(fs.existsSync(path.join(partialRoot,'employee-0'+i+'-adoption-receipt.json')));const resumeClient=new FakeClient(root),resumed=await adoption.run({...common,outputRoot:partialRoot,client:resumeClient});assert.equal(resumed.status,'verified');assert.deepEqual(resumeClient.started.map(x=>x.threadId),THREADS.slice(3).map(x=>x.thread_id));assert.equal(resumeClient.firstStartReads,5);
const tampered=path.join(output,'employee-01-adoption-receipt.json'),original=await fsp.readFile(tampered);const bad=JSON.parse(original);bad.bindings.install_receipt_sha256='0'.repeat(64);await write(tampered,bad);await assert.rejects(()=>adoption.run({...common,outputRoot:output,client:new FakeClient(root)}),/replay_invalid/);await fsp.writeFile(tampered,original);
const manifestPath=path.join(output,'adoption-manifest.json'),manifestOriginal=await fsp.readFile(manifestPath),employee2=path.join(output,'employee-02-adoption-receipt.json'),employee2Original=await fsp.readFile(employee2);for(const value of [true,undefined]){const manifest=JSON.parse(manifestOriginal);if(value===undefined)delete manifest.local_image_editing_requested;else manifest.local_image_editing_requested=value;await write(manifestPath,manifest);await assert.rejects(()=>adoption.run({...common,outputRoot:output,client:new FakeClient(root)}),/v2_adoption_replay_manifest_invalid/);}await fsp.writeFile(manifestPath,manifestOriginal);for(const injected of [THREADS[0].thread_id,'019f0000-0000-0000-0000-000000000000']){const receipt=JSON.parse(employee2Original);receipt.thread_id=injected;receipt.employee_response.parsed_ack.thread_id=injected;await write(employee2,receipt);const receiptBytes=await fsp.readFile(employee2),manifest=JSON.parse(manifestOriginal);manifest.receipts[1].sha256=hash(receiptBytes);manifest.receipts[1].bytes=receiptBytes.length;await write(manifestPath,manifest);await assert.rejects(()=>adoption.run({...common,outputRoot:output,client:new FakeClient(root)}),/replay_invalid/);}await fsp.writeFile(employee2,employee2Original);await fsp.writeFile(manifestPath,manifestOriginal);
await assert.rejects(()=>adoption.run({...common,outputRoot:path.join(root,'wrong'),client:new FakeClient(root,{wrongResponseIndex:0}),readbackAttempts:1}),/response_binding_invalid/);await assert.rejects(()=>adoption.run({...common,outputRoot:path.join(root,'turn-error'),client:new FakeClient(root,{turnErrorIndex:0})}),/turn_not_completed/);
const driftCandidate=JSON.parse(await fsp.readFile(f.candidatePath,'utf8'));driftCandidate.revision_marker='candidate-drift';await write(f.candidatePath,driftCandidate);const driftClient=new FakeClient(root),driftResult=await adoption.run({...common,outputRoot:output,client:driftClient});assert.equal(driftClient.started.length,5);assert.equal(driftResult.bindings.toolchain_candidate_sha256,hash(await fsp.readFile(f.candidatePath)));
const staticConfig=path.join(root,'static.toml');await fsp.writeFile(staticConfig,'model_provider="codex_local_access"\nexperimental_bearer_token="forbidden"\n[model_providers.codex_local_access]\nenv_key="KRILL_CODEX_API_KEY"\nwire_api="responses"\nrequires_openai_auth=false\n');const staticClient=new FakeClient(root);const staticResult=await adoption.run({...f,projectRoot:root,outputRoot:path.join(root,'static'),configPath:staticConfig,client:staticClient});assert.equal(staticResult.status,'verified');assert.equal(staticClient.started.length,5);
process.stdout.write(JSON.stringify({ok:true,verified:['real-shaped install/parity schema and exact four unmanaged','all five thread reads before any start','fourth active means total zero start','durable per-employee partial resume without duplicate','existing exact receipt replay zero duplicate','exact employee response text/SHA/bytes/parsed ack plus turn counts','exact five unique fixed receipts and manifest evidence SHA','manifest local-image-edit true and missing rejected','tampered cross-binding rejected','explicit duplicate and nonfixed thread injection rejected','wrong response and turn error rejected','native openai default model is bound on resume and turn start','unused legacy provider static fields cannot enter native launch route','all media/source/local-image-edit/spend/deploy effects false']})+'\n');}finally{await fsp.rm(root,{recursive:true,force:true});}}
main().catch(e=>{process.stderr.write(String(e.stack||e)+'\n');process.exitCode=1;});
